{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Pregnant women are considered a high risk group because of concerns about the effect of covid-19 on them during and after pregnancy, and on their neonates. 3 Quantification of the rates of covid-19, its risk factors, clinical manifestations, and outcomes is key to planning clinical maternal care and management in an evolving pandemic scenario.",
      "reason": "Describes the existing context/knowledge gaps by emphasizing why pregnancy is high risk and that quantification of key outcomes (rates, risk factors, manifestations, outcomes) is needed."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "In this unprecedented pandemic situation, where evidence is rapidly produced and published in various formats, our living systematic review underpinned by robust methods and continually updated at regular intervals is important for several reasons. Firstly, it addresses important research questions relevant to clinical decision making and policies. Secondly, uncertainties remain for key outcomes that require further evidence.",
      "reason": "Explains why conducting the review is important, linking it to clinical/policy decision-making and stating that uncertainties remain for key outcomes."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was retrieved describing similar systematic reviews or citing prior reviews to justify the need for this current (update) review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Cohort studies reporting the rates, clinical manifestations (symptoms, laboratory and radiological findings), risk factors, and maternal and perinatal outcomes in pregnant and recently pregnant women with suspected or confirmed covid-19.",
      "reason": "The review focuses on observational cohort data for rates/outcomes (not an intervention effect), so describing a proposed mechanism of action of an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Cohort studies reporting the rates, clinical manifestations (symptoms, laboratory and radiological findings), risk factors, and maternal and perinatal outcomes in pregnant and recently pregnant women with suspected or confirmed covid-19.",
      "reason": "No complex intervention or delivery context is described in the retrieved evidence; therefore, a logic model of hypothesised relationships between intervention components and outcomes is not applicable."
    }
  ],
  "confidence": 63
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Our systematic review is based on a prospectively registered protocol (PROSPERO CRD42020178076; registered 22 April 2020) 19 to evaluate a series of research questions on covid-19 during and after pregnancy.",
      "reason": "The review states that it will “evaluate a series of research questions” on covid-19 during and after pregnancy, but the retrieved evidence does not explicitly list all objectives/questions in a clearly stated question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_15",
      "quote": "We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19.",
      "reason": "The retrieved evidence describes observational comparisons (e.g., pregnant vs non-pregnant; with vs without covid-19), not intervention effects; therefore planned intervention comparisons using PICO (or variant) are not applicable based on the available evidence."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19. In studies comparing maternal and perinatal outcomes of pregnant women with covid-19 to those without, we classified the comparative controls as being historical if the cohort of pregnant women without covid-19 gave birth before December 2019. Studies on noncomparative cohorts with a minimum of 10 participants were included if they reported on the rates and clinical manifestations of covid-19 and relevant outcomes in pregnant and recently pregnant women.",
      "reason": "Eligibility characteristics relevant to populations (pregnant/recently pregnant/non-pregnant), comparisons (with vs without COVID-19; historical controls), and eligible study types (comparative cohorts; noncomparative cohorts with minimum 10 participants) are specified, but the evidence does not fully show all question-framework components, eligible study designs/settings, and follow-up requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "No language restrictions were applied.",
      "reason": "Language restriction is explicitly addressed, but dissemination year and publication/report status criteria are not clearly specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe whether exclusions were distinguished by outcomes not measured versus outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "The recently pregnant group comprised women in the postpartum and post-abortion period. We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19.",
      "reason": "The evidence defines key groups (pregnant, recently pregnant/postpartum & post-abortion, non-pregnant, and controls with/without COVID-19) used to support comparisons, but it does not clearly specify the groups used in each synthesis or explicitly link each synthesis group to the review objectives in the retrieved material."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "We excluded studies if the duplicated data for all outcomes of interest were published elsewhere, as reported by the study authors, or when the characteristics of the women or neonates matched the setting, characteristics, and duration of another study from the same geographical location. If there was an overlap of data or suspicion of duplicates of participants in studies, we included studies based on their study design (prioritising comparative cohorts), and sample size (larger study prioritised).",
      "reason": "Rationales for handling duplicate/overlapping data are provided (how exclusion/inclusion decisions were made). However, the retrieved evidence does not present rationales for all notable eligibility restrictions."
    }
  ],
  "confidence": 58
}

